    },
    {
      "key_point": "S3.K2",
      "question": "What is the primary objective of using Bresenham's line drawing algorithm?",
      "answer": "The objective is to have efficient algorithms that can render a line by avoiding floating point operations."
    },
    {
      "key_point": "S3.K3",
      "question": "How does Bresenham's algorithm achieve faster line rendering?",
      "answer": "The entire operation is done based on integer arithmetic, addition, and multiplication, which speeds up the rendering of lines."
    },
    {
      "key_point": "S3.K4",
      "question": "What initial parameters must be computed before the line drawing loop begins?",
      "answer": "We must compute delta x (the difference between the two endpoint x coordinates), delta y (the difference between the two endpoint y coordinates), and the decision parameter p."
    }
  ],
